Implementation details:

```js
const TimbreAudio = (() => {
  const TARGET_SR = 24000;

  function download blob? no.

  function encodeWav(float32, sampleRate=24000) {
    const buffer = new ArrayBuffer(44 + float32.length*2);
    const view = new DataView(buffer);
    writeString(view,0,'RIFF'); view.setUint32(4, 36 + float32.length*2, true); ...
    for (...) { const s = Math.max(-1, Math.min(1, float32[i])); view.setInt16(44+i*2, s<0? s*0x8000 : s*0x7fff, true); }
    return new Blob([view], {type:'audio/wav'});
  }

  function toMono(buffer) { mix channels into Float32Array }

  async function resampleMono(samples, srcRate, dstRate=TARGET_SR) {
    if (srcRate === dstRate) return samples;
    const length = Math.max(1, Math.round(samples.length * dstRate / srcRate));
    const ctx = new OfflineAudioContext(1, length, dstRate);
    const buf = ctx.createBuffer(1, samples.length, srcRate);
    buf.copyToChannel(samples, 0);
    const src = ctx.createBufferSource(); src.buffer=buf;
    src.connect(ctx.destination); src.start();
    const rendered = await ctx.startRendering();
    return rendered.getChannelData(0).slice();
  }
```
Note createBuffer with sampleRate srcRate on OfflineAudioContext: allowed (AudioBuffer sampleRate independent). OK.

```js
  async function decodeArrayBuffer(arrayBuffer) {
    const Ctx = window.AudioContext || window.webkitAudioContext;
    const ctx = new Ctx();
    try { return await ctx.decodeAudioData(arrayBuffer.slice(0)); } finally { ctx.close(); }
  }
```
Safari requires callback form but fine.

```js
  async function blobToPeaks(blob, buckets=64) { const ab = await blob.arrayBuffer(); const buf = await decodeArrayBuffer(ab); const mono = toMono(buf); return peaks(mono, buckets); }

  function peaks(samples, buckets=64) {
    const count = Math.max(8, buckets);
    const block = Math.floor(samples.length / count) || 1;
    const out = new Array(count).fill(0);
    for (i...) { let max=0; for (j...) max=Math.max(max, Math.abs(samples[...])); out[i]=max; }
    // normalize to max 1 (with floor)
    const peak = Math.max(...out, 0.0001);
    return out.map(v => Math.max(0.04, Math.min(1, v/peak)));
  }
```
Normalizing per clip may exaggerate noise. Use absolute scale with fixed reference 0.5? Use peak normalization but floor; ok for visualization.

Draw:
```js
  function drawWave(canvas, peaksArr, opts={}) {
    const dpr = Math.min(2, window.devicePixelRatio||1);
    const w = canvas.clientWidth || 300, h = canvas.clientHeight || 40;
    canvas.width = w*dpr; canvas.height = h*dpr;
    ctx.scale(dpr,dpr);
    ctx.clearRect(0,0,w,h);
    const n = peaksArr.length; const gap = 1.6; const bw = Math.max(1, (w - gap*(n-1))/n);
    const progress = opts.progress ?? 0;
    const grad = ctx.createLinearGradient(0,0,w,0);
    ... color? Use single color with alpha by index relative to progress:
    for i: x = i*(bw+gap); amp = peaks[i]*(h-4)/2; y=h/2;
      const played = (i+0.5)/n <= progress;
      ctx.fillStyle = played ? (opts.activeColor||'#a78bfa') : (opts.color||'rgba(255,255,255,0.22)');
      roundRect bars
  }
```
Height mirrors.

Recorder:
```js
  function createRecorder({onLevel, onTick}={}) {
    let stream, ctx, proc, source, mute, chunks, startedAt, raf, running=false;
    async function start() {
      stream = await navigator.mediaDevices.getUserMedia({audio:{echoCancellation:false, noiseSuppression:false, autoGainControl:false, channelCount:1}});
      const Ctx = window.AudioContext||window.webkitAudioContext;
      ctx = new Ctx();
      if (ctx.state === 'suspended') await ctx.resume();
      source = ctx.createMediaStreamSource(stream);
      proc = ctx.createScriptProcessor(4096,1,1);
      mute = ctx.createGain(); mute.gain.value = 0;
      chunks = [];
      proc.onaudioprocess = (e) => {
        if (!running) return;
        const input = e.inputBuffer.getChannelData(0);
        chunks.push(new Float32Array(input));
        if (onLevel) { let sum=0; for...; onLevel(Math.min(1, Math.sqrt(sum/input.length)*4)); }
      };
      source.connect(proc); proc.connect(mute); mute.connect(ctx.destination);
      running = true; startedAt = performance.now();
      return true;
    }
    async function stop() {
      if (!running) return null;
      running = false;
      const duration = (performance.now()-startedAt)/1000;
      proc.onaudioprocess = null;
      try { source.disconnect(); proc.disconnect(); mute.disconnect(); } catch {}
      stream.getTracks().forEach(t=>t.stop());
      const sr = ctx.sampleRate;
      await ctx.close();
      const total = chunks.reduce((a,c)=>a+c.length,0);
      const merged = new Float32Array(total); let o=0; for (const c of chunks) { merged.set(c,o); o+=c.length; }
      onLevel && onLevel(0);
      if (!total) return null;
      const resampled = await resampleMono(merged, sr, TARGET_SR);
      const blob = encodeWav(resampled, TARGET_SR);
      return { blob, duration: resampled.length/TARGET_SR, peaks: peaks(resampled, 80), size: blob.size };
    }
    function cancel(){ ...stop without result, stop tracks }
  }
```
