```js
async function request(path, {method='GET', body=null, form=null, timeout=180000}={}) {
  const controller = new AbortController();
  const timer = setTimeout(()=>controller.abort(), timeout);
  try {
    const options = {method, signal: controller.signal, headers:{}};
    if (form) options.body = form;
    else if (body !== null) { options.headers['Content-Type']='application/json'; options.body=JSON.stringify(body); }
    const res = await fetch(API_BASE + path, options);
    const type = res.headers.get('content-type') || '';
    const data = type.includes('application/json') ? await res.json().catch(()=>null) : await res.text();
    if (!res.ok) {
      let detail = data && data.detail ? data.detail : (typeof data === 'string' && data ? data : `Request failed (${res.status})`);
      if (Array.isArray(detail)) detail = detail.map(d => d.msg || JSON.stringify(d)).join('; ');
      throw new ApiError(detail || `Request failed (${res.status})`, res.status);
    }
    return data;
  } catch(err) {
    if (err.name === 'AbortError') throw new ApiError('The engine took too long to respond.', 0);
    if (err instanceof ApiError) throw err;
    throw new ApiError('Cannot reach the local engine. Is the server running?', 0);
  } finally { clearTimeout(timer); }
