const players = new Map();

function initPlayers(root) {
  root.querySelectorAll('.player').forEach(el => {
    if (el.dataset.ready) return;
    el.dataset.ready = '1';
    const id = el.dataset.player;
    const audio = new Audio(el.dataset.src);
    audio.preload = 'metadata';
    const canvas = el.querySelector('canvas');
    const time = el.querySelector('.player-time');
    const btn = el.querySelector('[data-action="player-toggle"]');
    let peaks = null;
    const draw = () => {
      if (!peaks) return;
      const progress = audio.duration ? audio.currentTime / audio.duration : 0;
      TimbreAudio.drawWave(canvas, peaks, {progress, idleColor:'rgba(173,181,199,0.22)', activeColor:'rgba(196,181,253,0.92)'});
      if (time) time.textContent = `${TimbreAudio.formatTime(audio.currentTime)} / ${TimbreAudio.formatTime(audio.duration || el.dataset.duration || 0)}`;
    };
    TimbreAudio.loadPeaks(el.dataset.src).then(p => { peaks = p; draw(); });
    audio.addEventListener('timeupdate', draw);
    audio.addEventListener('ended', () => { btn.classList.remove('playing'); btn.innerHTML = icon('play'); draw(); });
    audio.addEventListener('loadedmetadata', draw);
    players.set(id, {audio, btn, el, draw});
  });
  // global pause others when one starts? handled in toggle
}
```
