function coverageCard(voice) {
  const rows = T.EMOTIONS.map(e => {
    const sample = voice.samples[e] || {seconds:0,count:0};
    const target = e === 'neutral' ? (voice.targets?.target_neutral||30) : (voice.targets?.target_emotion||15);
    const pct = Math.min(100, Math.round(sample.seconds/target*100));
    const ready = (voice.emotions_ready||[]).includes(e);
    return `<div class="coverage-row ${e==='neutral'?'required':''}" data-action="sample-tab" data-emotion="${e}" role="button" tabindex="0" title="Show ${e} samples">
      <span class="coverage-name"><span class="dot ${e}"></span>${e}</span>
      <span class="coverage-bar"><span class="coverage-fill" style="width:${pct}%;--emo-color:${T.EMOTION_COLORS[e]}"></span></span>
      <span class="coverage-time">${sample.seconds ? T.fmtDur(sample.seconds) : '—'} / ${target}s</span>
      <span class="coverage-state ${ready?'on':'off'}">${ready?'trained':'—'}</span>
    </div>`;
  }).join('');
  return `<section class="card"><div class="card-head"><div><h2>Emotion coverage</h2><p>Neutral is the base. Add the moods you want to perform.</p></div><span class="pill ${...}">${ready} trained</span></div><div class="coverage-list">${rows}</div></section>`;
}
