Training card: include `id="trainCard"` and `.train-msg`, `.progress-fill`, `.job-log`.

```js
function trainingCard(voice, neutralSeconds, minNeutral) {
  const job = voice.job;
  const running = voice.status === 'training';
  const ready = voice.emotions_ready || [];
  const missing = minNeutral - neutralSeconds;
  return `<section class="card rail-card" id="trainCard">
    <div class="card-head" style="margin-bottom:10px"><h2>Training</h2>${T.statusPill(voice)}</div>
    ${running ? `
      <p class="hint train-msg">${esc(job?.message || 'Starting…')}</p>
      <div class="progress"><div class="progress-fill" style="width:${Math.max(2, job?.progress||0)}%"></div></div>
      <div class="job-log">${esc(job?.log || '')}</div>
      <p class="hint" style="margin-top:8px">You can leave this page — training continues in the background.</p>
    ` : `
      ${voice.status === 'error' ? `<div class="banner err" style="margin-bottom:10px">${esc(voice.error || 'Training failed.')}</div>` : ''}
      <p class="hint">Each trained emotion gets its own conditioning, so you can switch mood at generation time.</p>
      <div class="readiness">
        ${T.EMOTIONS.filter(e => ready.includes(e)).map(e => `<div class="readiness-row"><span><span class="dot ${e}"></span>${e}</span><span class="val ok">trained</span></div>`).join('') || `<div class="readiness-row"><span>No emotions trained</span><span class="val">—</span></div>`}
      </div>
      ${missing > 0 ? `<div class="banner" style="margin-top:10px">Add ${T.fmtDur(missing)} more neutral audio to unlock training.</div>` : ''}
      <button class="btn primary full" style="margin-top:12px" type="button" data-action="train" ${missing > 0 ? 'disabled' : ''}>${ready.length ? 'Retrain voice' : 'Train voice'}</button>
      ${ready.length === 1 ? `<p class="hint" style="margin-top:8px">Only neutral is trained. Add happy, sad or angry takes for emotional range.</p>` : ''}
      ${voice.model?.trained_at ? `<p class="hint" style="margin-top:8px">Last trained ${T.fmtDateTime(voice.model.trained_at)}${voice.model.stale ? ' · samples changed since' : ''}</p>` : ''}
      ${job?.log && job.status === 'error' ? `<div class="job-log">${esc(job.log)}</div>` : ''}
    `}
  </section>`;
}
```

Tips card: active tab tip + best practices:
```js
<section class="card rail-card">
 <h2>Recording ${tab}</h2>
