function bindVoice(view) {
  const input = view.querySelector('#clipFileInput');
  if (input) input.addEventListener('change', async () => { const files=[...input.files]; input.value=''; if (files.length) await addFiles(files); });
  const dz = view.querySelector('#dropzone');
  if (dz) {
    ['dragenter','dragover'].forEach(ev => dz.addEventListener(ev, e => {e.preventDefault(); dz.classList.add('drag');}));
    ['dragleave','drop'].forEach(ev => dz.addEventListener(ev, e => {e.preventDefault(); dz.classList.remove('drag');}));
    dz.addEventListener('drop', async e => { const files=[...(e.dataTransfer?.files||[])]; if (files.length) await addFiles(files); });
  }
  hydrateWaves(view);
}
