addFiles:
```js
async function addFiles(files) {
  const voice = state.voice; if (!voice) return;
  const emotion = state.detailTab;
  const status = document.getElementById('dropStatus');
  let added = 0;
  for (const file of files) {
    if (status) { status.hidden = false; status.textContent = `Preparing ${file.name}…`; }
    try {
      const wav = await A.fileToWav(file);
      if (status) status.textContent = `Uploading ${file.name}…`;
      await T.api(`/api/voices/${voice.id}/clips`, {method:'POST', form: buildForm(emotion, wav.blob, ''), timeout: 120000});
      added += 1;
    } catch (error) { T.toast(`${file.name}: ${error.message}`, 'err'); }
  }
  if (added) {
    T.toast(`${added} sample${added===1?'':'s'} added to ${emotion}.`, 'ok');
    await loadVoiceData(voice.id);
    paintVoice(document.getElementById('view'));
  } else if (status) { status.hidden = true; }
}
```
