```js
function startJobPolling(jobId, voiceId) {
  stopJobPolling();
  state.pollingJob = jobId;
  const tick = async () => {
    if (state.pollingJob !== jobId) return;
    try {
      const job = await T.api(`/api/jobs/${jobId}`, {timeout: 15000});
      if (state.voice && state.voice.id === voiceId) {
        state.voice.job = job;
        if (job.status === 'running' || job.status === 'queued') state.voice.status='training';
      }
      updateTrainUI(job);
      if (job.status === 'done' || job.status === 'error') {
        const ok = job.status === 'done';
        stopJobPolling();
        T.toast(ok ? 'Training complete — voice ready.' : `Training failed: ${job.error || job.message}`, ok?'ok':'err');
        await refreshVoicesQuiet();
        if (state.route.name === 'voice' && state.route.id === voiceId) {
          await loadVoiceData(voiceId);
          paintVoice(document.getElementById('view'));
        }
      }
    } catch (_) { /* transient */ }
  };
  tick();
  state.pollTimer = setInterval(tick, 1500);
}
function stopJobPolling(){ if (state.pollTimer) clearInterval(state.pollTimer); state.pollTimer=null; state.pollingJob=null; }
function updateTrainUI(job) {
  const card = document.getElementById('trainCard'); if (!card) return;
  const fill = card.querySelector('.progress-fill'); if (fill && typeof job.progress==='number') fill.style.width = `${Math.max(2, job.progress)}%`;
  const msg = card.querySelector('.train-msg'); if (msg) msg.textContent = job.message || '';
  const log = card.querySelector('.job-log'); if (log) { log.textContent = job.log || ''; log.scrollTop = log.scrollHeight; }
  const pill = card.querySelector('.pill'); if (pill) {...} // skip
}
