async function renderStudio(view, params) {
  const voices = await T.api('/api/voices');
  state.voices = voices; T.updateNavCount();
  const requested = params?.get('voice');
  if (requested) state.studio.voiceId = requested;
  let voice = voices.find(v=>v.id===state.studio.voiceId) || voices.find(v=>v.status==='ready') || voices[0] || null;
  if (requested) voice = voices.find(v=>v.id===requested) || voice;
  if (!voice) { view.innerHTML = emptyStudio(); return; }
  state.studio.voiceId = voice.id;
  const ready = voice.emotions_ready || [];
  if (!ready.includes(state.studio.emotion)) state.studio.emotion = ready.includes('neutral') ? 'neutral' : (ready[0] || 'neutral');
  if (!state.studio.language) state.studio.language = voice.language;
  // if lastGeneration belongs to another voice, drop it
  if (state.lastGeneration && state.lastGeneration.voice_id !== voice.id) state.lastGeneration = null;
  view.innerHTML = studioHtml(voice);
  bindStudio(view, voice);
  hydrateWaves(view);
  paintResult();
  updateSliders();
}
