async function generateSpeech() {
  if (state.generating) return;
  const voice = T.state.voices.find(v=>v.id===state.studio.voiceId);
  if (!voice) return;
  if (voice.status !== 'ready' || !voice.emotions_ready.length) { toast('Train this voice first.','warn'); return; }
  const text = (document.getElementById('script')?.value || '').trim();
  if (!text) { toast('Write something for the voice to say.','warn'); return; }
  if (text.length > 2000) ...
  state.generating = true;
  T.persist('studio', state.studio);
  const btn = document.getElementById('generateBtn');
  if (btn) { btn.disabled = true; btn.innerHTML = `<span class="spin">${icon('refresh')}</span> Generating…`; }
  const result = document.getElementById('resultCard');
  if (result) result.innerHTML = `<div class="generating"><div class="eq">${'<span></span>'.repeat(8)}</div><div><strong>Rendering ${esc(state.studio.emotion)} speech</strong><p class="hint">Local XTTS inference. This can take a few seconds on first run.</p></div></div>`;
  try {
    const gen = await T.api(`/api/voices/${voice.id}/speak`, {method:'POST', body:{text, emotion: state.studio.emotion, intensity: state.studio.intensity, speed: state.studio.speed, language: state.studio.language}, timeout: 300000});
    state.lastGeneration = gen;
    paintResult();
    T.toast('Speech generated.', 'ok');
  } catch (error) {
    paintResult();
    T.toast(error.message, 'err');
  } finally {
    state.generating = false;
    if (btn) { btn.disabled = false; btn.innerHTML = `${icon('sparkles')} Generate speech`; }
  }
}
