function paintResult() {
  const host = document.getElementById('resultCard'); if (!host) return;
  const gen = state.lastGeneration;
  if (!gen) { host.innerHTML = emptyResult(); return; }
  const voice = state.voices.find(v=>v.id===gen.voice_id);
  host.innerHTML = `
   <div class="result-head">
    <div class="result-title"><span class="dot ${gen.emotion}"></span><h3>Latest take</h3></div>
    <div class="result-meta">${esc(voice?.name || gen.voice_name || '')} · ${gen.emotion} · ${T.fmtDur(gen.duration)}</div>
   </div>
   ${T.playerHtml('last', gen.url, gen.duration)}
   <div class="result-meta" style="margin-top:10px">${esc(gen.engine || 'local')} · ${gen.speed.toFixed(2)}× · intensity ${Math.round(gen.intensity*100)}% · ${T.fmtDateTime(gen.created_at)}</div>`;
  initPlayers(host);
  hydrateWaves(host);
}
```
Player for 'last' registers map key 'last'; new generation → re-init but map has 'last' from previous; `initPlayers` checks `data-ready` on new element (fresh), but map key 'last' exists → overwrite with new audio
